import numpy as np
from sklearn.base import BaseEstimator, RegressorMixin

class RecentBL0Bias(BaseEstimator, RegressorMixin):
    def fit(self, X, y):
        X = np.asarray(X, dtype=float)
        y = np.asarray(y, dtype=float)
        keep = X[:, -1] >= np.max(X[:, -1]) - 24 * 21 + 1
        X, y = X[keep], y[keep]
        if len(y) < 12:
            raise ValueError("筛选后训练参考少于12条")
        self.bias_ = float(np.mean(y - X[:, 0]))
        return self

    def predict(self, X):
        X = np.asarray(X, dtype=float)
        return np.maximum(0.0, X[:, 0] + 0.5 * self.bias_)

def build_model():
    return RecentBL0Bias()

